import{_ as a,o,c as t,a0 as r}from"./chunks/framework.BdKrsJIB.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),c={name:"explanation/concepts.md"};function d(n,e,i,s,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The domain vocabulary, each term defined once. Field-level contracts live in <a href="./../reference/">Reference</a>.</p><h2 id="release-unit" tabindex="-1">Release unit <a class="header-anchor" href="#release-unit" aria-label="Permalink to &quot;Release unit&quot;">​</a></h2><p>One independently versioned thing — a cargo workspace member or an explicitly declared unit. Units resolve their own commit range (<code>{latest-tag-for-that-unit}..HEAD</code>) and release only when their paths changed.</p><h2 id="op" tabindex="-1">Op <a class="header-anchor" href="#op" aria-label="Permalink to &quot;Op&quot;">​</a></h2><p>The unit of the <code>tarsi-serve</code> wire: <code>manifest</code>, <code>profiles</code>, <code>plan</code>, <code>changelog</code>, <code>notes</code>, <code>check</code>, <code>schema</code>, <code>bump</code>, <code>tag</code>, <code>publish</code>, <code>release</code>. One JSON object in, one result out — identical for humans, agents, and campaigns.</p><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><p>The computed, unwritten release: per-unit bump, <code>new_version</code>, tag, rendered changelog, publish targets, <code>steps</code> — plus <code>unattributed</code> commits. <code>plan</code> is the review gate; <code>release</code> executes it.</p><h2 id="bump-strategy" tabindex="-1">Bump strategy <a class="header-anchor" href="#bump-strategy" aria-label="Permalink to &quot;Bump strategy&quot;">​</a></h2><p>The data-driven rule table mapping commit types to semver bumps — <code>[release] strategy</code> in <code>tarsi.toml</code>, defaulting to <code>conventional</code>. <code>semantic-release-angular</code> ships the angular preset; <code>keep-a-changelog</code> keeps the same bumps with KaC section names. <code>spec.bump</code> and <code>release.default_bump</code> override inference.</p><h2 id="tag-format" tabindex="-1">Tag format <a class="header-anchor" href="#tag-format" aria-label="Permalink to &quot;Tag format&quot;">​</a></h2><p><code>{unit}-v{version}</code> per unit (<code>tamias-core-v0.4.2</code>) — not a repo-level <code>v{semver}</code>.</p><h2 id="profile-pack" tabindex="-1">Profile pack <a class="header-anchor" href="#profile-pack" aria-label="Permalink to &quot;Profile pack&quot;">​</a></h2><p>A <code>type: tarsi</code> tamias package carrying org release defaults — layered config resolved by <code>tarsi-config</code> through scarab-config. Shipped via <code>libraries/9aia-release</code>.</p><h2 id="publish-target" tabindex="-1">Publish target <a class="header-anchor" href="#publish-target" aria-label="Permalink to &quot;Publish target&quot;">​</a></h2><p>A forge destination — <code>crates</code> (crates.io), <code>ghreleases</code> (GitHub Releases), <code>dryrun</code>. Org repos keep both off: releases are tag-only and crates.io publishing is tamias-only.</p><h2 id="dry-run" tabindex="-1">Dry-run <a class="header-anchor" href="#dry-run" aria-label="Permalink to &quot;Dry-run&quot;">​</a></h2><p>The default for every <code>release</code>-family op: full plan + dry-run publish, zero writes. Mutation requires <code>dry_run: false</code> (<code>--yes</code>).</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Ordered mutation (changelogs → manifests → scoped add → bump commit → tags → push → publish) with exact undo: remote tags deleted, branch reset, created files removed. Publish failures roll back only if <em>nothing</em> published.</p>',20)])])}const m=a(c,[["render",d]]);export{u as __pageData,m as default};
